package xfcc_test

import (
	"errors"
	"os"
	"strings"
	"testing"

	"github.com/motrice/smartcard-op/internal/adapters/xfcc"
)

// golden reads the header generated by a standalone encoder applying Envoy's
// own percent-encoding rules, not by the code under test.
func golden(t *testing.T) string {
	t.Helper()

	data, err := os.ReadFile("testdata/xfcc_golden.txt")
	if err != nil {
		t.Fatalf("could not read the golden header: %v", err)
	}

	return string(data)
}

func fingerprint(t *testing.T) string {
	t.Helper()

	data, err := os.ReadFile("testdata/cert_sha256.txt")
	if err != nil {
		t.Fatalf("could not read the fingerprint: %v", err)
	}

	return strings.TrimSpace(string(data))
}

func TestParseReadsEnvoysHeader(t *testing.T) {
	t.Parallel()

	cert, err := xfcc.Parse([]string{golden(t)})
	if err != nil {
		t.Fatalf("Parse returned error: %v", err)
	}

	if got := cert.Subject.CommonName; got != "Anna Andersson" {
		t.Errorf("CommonName = %q, want %q", got, "Anna Andersson")
	}

	// Go maps OID 2.5.4.5 into the named field.
	if got := cert.Subject.SerialNumber; got != "195606019577" {
		t.Errorf("Subject.SerialNumber = %q, want %q", got, "195606019577")
	}
}

// Envoy always sets Hash to SHA-256 over the leaf's DER. If it does not match
// what we compute ourselves, either our parsing is wrong or the header was
// tampered with — both must be hard failures, not warnings.
func TestParseCrossChecksTheFingerprint(t *testing.T) {
	t.Parallel()

	if _, err := xfcc.Parse([]string{golden(t)}); err != nil {
		t.Fatalf("the correct fingerprint was rejected: %v", err)
	}

	tampered := strings.Replace(golden(t),
		"Hash="+fingerprint(t), "Hash="+strings.Repeat("0", 64), 1)

	_, err := xfcc.Parse([]string{tampered})
	if !errors.Is(err, xfcc.ErrFingerprintMismatch) {
		t.Errorf("error = %v, want ErrFingerprintMismatch", err)
	}
}

// Subject and Issuer are RFC 2253 distinguished names and contain raw commas
// and equals signs. A naive split on ';' or ',' shreds them, and Cert= is then
// no longer found.
func TestParseToleratesQuotedValuesWithSeparators(t *testing.T) {
	t.Parallel()

	modified := strings.Replace(golden(t),
		`Subject="CN=Anna Andersson,OU=2021005208,O=Testmyndigheten,C=SE"`,
		`Subject="CN=Andersson\, Anna;x=y,OU=2021005208,O=Testmyndigheten,C=SE"`, 1)

	cert, err := xfcc.Parse([]string{modified})
	if err != nil {
		t.Fatalf("Parse returned error: %v", err)
	}

	if cert.Subject.CommonName != "Anna Andersson" {
		t.Errorf("CommonName = %q", cert.Subject.CommonName)
	}
}

func TestParseIsCaseInsensitiveInKeyNames(t *testing.T) {
	t.Parallel()

	for _, key := range []string{"cert=", "CERT=", "CeRt="} {
		modified := strings.Replace(golden(t), "Cert=", key, 1)
		if _, err := xfcc.Parse([]string{modified}); err != nil {
			t.Errorf("the key %q was rejected: %v", key, err)
		}
	}
}

func TestParseRejectsMalformedHeaders(t *testing.T) {
	t.Parallel()

	goldenHeader := golden(t)

	cases := map[string]struct {
		headers []string
		wantErr error
	}{
		"no header at all": {
			headers: nil,
			wantErr: xfcc.ErrHeaderMissing,
		},
		"empty header": {
			headers: []string{""},
			wantErr: xfcc.ErrHeaderMissing,
		},
		"two header values": {
			headers: []string{goldenHeader, goldenHeader},
			wantErr: xfcc.ErrMoreThanOneCertificate,
		},
		"two elements in one header": {
			headers: []string{goldenHeader + "," + goldenHeader},
			wantErr: xfcc.ErrMoreThanOneCertificate,
		},
		"cert missing": {
			headers: []string{`By=spiffe://x;Hash=` + strings.Repeat("0", 64)},
			wantErr: xfcc.ErrCertificateMissing,
		},
		"malformed percent-encoding": {
			headers: []string{strings.Replace(goldenHeader, "%0A", "%ZZ", 1)},
			wantErr: xfcc.ErrUnparsableCertificate,
		},
		"truncated percent-encoding": {
			headers: []string{strings.Replace(goldenHeader, "%0A", "%0", 1)},
			wantErr: xfcc.ErrUnparsableCertificate,
		},
		"not pem": {
			headers: []string{`Hash=x;Cert="not%20a%20certificate"`},
			wantErr: xfcc.ErrUnparsableCertificate,
		},
	}

	for name, testCase := range cases {
		t.Run(name, func(t *testing.T) {
			t.Parallel()

			_, err := xfcc.Parse(testCase.headers)
			if err == nil {
				t.Fatal("Parse returned no error, want one")
			}

			if !errors.Is(err, testCase.wantErr) {
				t.Errorf("error = %v, want %v", err, testCase.wantErr)
			}
		})
	}
}

// The header carries a certificate and can grow large. A cap stops an attacker
// from forcing us to decode megabytes before we even look at the content.
func TestParseRejectsUnreasonablyLargeHeaders(t *testing.T) {
	t.Parallel()

	huge := `Cert="` + strings.Repeat("A", 64*1024) + `"`

	_, err := xfcc.Parse([]string{huge})
	if !errors.Is(err, xfcc.ErrHeaderTooLarge) {
		t.Errorf("error = %v, want ErrHeaderTooLarge", err)
	}
}

// Cert must carry exactly one certificate. Several blocks are an ambiguity we
// should not guess our way out of.
func TestParseRejectsSeveralPEMBlocksInCert(t *testing.T) {
	t.Parallel()

	goldenHeader := golden(t)
	encoded := goldenHeader[strings.Index(goldenHeader, `Cert="`)+len(`Cert="`) : len(goldenHeader)-1]
	doubled := `Hash=x;Cert="` + encoded + encoded + `"`

	_, err := xfcc.Parse([]string{doubled})
	if !errors.Is(err, xfcc.ErrUnparsableCertificate) {
		t.Errorf("error = %v, want ErrUnparsableCertificate", err)
	}
}

func FuzzParse(f *testing.F) {
	f.Add(golden(&testing.T{}))
	f.Add(`Cert="x"`)
	f.Add(`Hash=;Subject="";Cert=""`)
	f.Add("")

	f.Fuzz(func(t *testing.T, header string) {
		// The requirement is that Parse must never panic, whatever the
		// input.
		_, _ = xfcc.Parse([]string{header})
	})
}
